const RAW='https://raw.githubusercontent.com/anuchit1tube168-cmd/vite-react-template/astra-read-cleanroom/astra-read/src/';
const SEC={'x-content-type-options':'nosniff','referrer-policy':'strict-origin-when-cross-origin','permissions-policy':'camera=(), microphone=(), geolocation=()','x-frame-options':'SAMEORIGIN'};
const enc=new TextEncoder();
const json=(data,status=200,extra={})=>new Response(JSON.stringify(data),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store',...SEC,...extra}});
const reply=(body,type,status=200)=>new Response(body,{status,headers:{'content-type':type,'cache-control':'public, max-age=60',...SEC}});
const bj=async req=>{try{return await req.json()}catch{return {}}};
const emailOk=e=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e)&&e.length<=254;
const bookOk=id=>typeof id==='string'&&/^[a-z0-9-]{2,64}$/.test(id);
const b64u=bytes=>btoa(String.fromCharCode(...bytes)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
const fromB64u=s=>Uint8Array.from(atob(s.replace(/-/g,'+').replace(/_/g,'/')+'==='.slice((s.length+3)%4)),c=>c.charCodeAt(0));
const hex=buf=>[...new Uint8Array(buf)].map(b=>b.toString(16).padStart(2,'0')).join('');
const rand=n=>{const a=new Uint8Array(n);crypto.getRandomValues(a);return a};
async function src(n){const r=await fetch(RAW+n,{cf:{cacheTtl:120,cacheEverything:true}});if(!r.ok)throw new Error('source_unavailable');return r.text()}
function unwrap(s,p){s=s.trim();if(s.startsWith(p))s=s.slice(p.length);return s.replace(/`;\s*$/,'')}
async function passwordHash(password,salt,iterations){const key=await crypto.subtle.importKey('raw',enc.encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',salt:fromB64u(salt),iterations},key,256);return b64u(new Uint8Array(bits))}
function safeEq(a,b){if(typeof a!=='string'||typeof b!=='string'||a.length!==b.length)return false;let x=0;for(let i=0;i<a.length;i++)x|=a.charCodeAt(i)^b.charCodeAt(i);return x===0}
function cookie(req,name){const raw=req.headers.get('cookie')||'';for(const part of raw.split(';')){const [k,...v]=part.trim().split('=');if(k===name)return decodeURIComponent(v.join('='))}return null}
async function tokenHash(token){return hex(await crypto.subtle.digest('SHA-256',enc.encode(token)))}
async function user(req,env){const token=cookie(req,'ar_session');if(!token||token.length<30)return null;const h=await tokenHash(token);return await env.DB.prepare('SELECT s.session_hash,s.reader_id,s.expires_at,r.display_name,a.email FROM sessions s JOIN reader_profiles r ON r.id=s.reader_id JOIN auth_accounts a ON a.reader_id=s.reader_id WHERE s.session_hash=? AND s.expires_at>CURRENT_TIMESTAMP').bind(h).first()}
async function newSession(env,readerId){await env.DB.prepare('DELETE FROM sessions WHERE expires_at<=CURRENT_TIMESTAMP').run();const token=b64u(rand(32)),h=await tokenHash(token),expires=new Date(Date.now()+30*86400000).toISOString();await env.DB.prepare('INSERT INTO sessions(session_hash,reader_id,expires_at) VALUES(?,?,?)').bind(h,readerId,expires).run();return token}
const sessionCookie=(token,maxAge=2592000)=>`ar_session=${encodeURIComponent(token)}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${maxAge}`;
async function cat(env){const q=await env.DB.prepare('SELECT id,title,author,genre,status,rating,chapter_count AS chapters,accent,description FROM books ORDER BY rating DESC,title ASC').all();const a=q.results||[];return {items:a,genres:['All',...new Set(a.map(x=>x.genre))]}}
async function api(req,env,u){const method=req.method.toUpperCase(),path=u.pathname;let m;
if(method==='GET'&&path==='/api/health'){const row=await env.DB.prepare('SELECT COUNT(*) AS books FROM books').first();return json({ok:true,service:'astra-read',version:'0.3.0',mode:'d1-session-auth',books:Number(row?.books||0),payments:false})}
if(method==='GET'&&path==='/api/catalog')return new Response(JSON.stringify(await cat(env)),{headers:{'content-type':'application/json; charset=utf-8','cache-control':'public, max-age=60',...SEC}});
if(method==='POST'&&path==='/api/auth/register'){const b=await bj(req),email=String(b.email||'').trim().toLowerCase(),password=String(b.password||''),name=String(b.display_name||'Reader').trim().slice(0,80);if(!emailOk(email))return json({error:'invalid_email'},400);if(password.length<10||password.length>128)return json({error:'password_policy'},400);if(name.length<2)return json({error:'invalid_display_name'},400);const exists=await env.DB.prepare('SELECT reader_id FROM auth_accounts WHERE email=?').bind(email).first();if(exists)return json({error:'email_in_use'},409);const rid=crypto.randomUUID().replace(/-/g,''),salt=b64u(rand(16)),iterations=100000,hash=await passwordHash(password,salt,iterations);try{await env.DB.batch([env.DB.prepare('INSERT INTO reader_profiles(id,display_name) VALUES(?,?)').bind(rid,name),env.DB.prepare('INSERT INTO auth_accounts(reader_id,email,password_salt,password_hash,password_iterations) VALUES(?,?,?,?,?)').bind(rid,email,salt,hash,iterations)]);const token=await newSession(env,rid);return json({ok:true,user:{id:rid,email,display_name:name}},201,{'set-cookie':sessionCookie(token)})}catch{return json({error:'register_failed'},500)}}
if(method==='POST'&&path==='/api/auth/login'){const b=await bj(req),email=String(b.email||'').trim().toLowerCase(),password=String(b.password||'');const a=await env.DB.prepare('SELECT a.reader_id,a.email,a.password_salt,a.password_hash,a.password_iterations,r.display_name FROM auth_accounts a JOIN reader_profiles r ON r.id=a.reader_id WHERE a.email=?').bind(email).first();if(!a)return json({error:'invalid_credentials'},401);const hash=await passwordHash(password,a.password_salt,Number(a.password_iterations));if(!safeEq(hash,a.password_hash))return json({error:'invalid_credentials'},401);const token=await newSession(env,a.reader_id);return json({ok:true,user:{id:a.reader_id,email:a.email,display_name:a.display_name}},200,{'set-cookie':sessionCookie(token)})}
if(method==='POST'&&path==='/api/auth/logout'){const token=cookie(req,'ar_session');if(token){await env.DB.prepare('DELETE FROM sessions WHERE session_hash=?').bind(await tokenHash(token)).run()}return json({ok:true},200,{'set-cookie':sessionCookie('',0)})}
if(method==='GET'&&path==='/api/auth/me'){const x=await user(req,env);if(!x)return json({error:'unauthorized'},401);return json({user:{id:x.reader_id,email:x.email,display_name:x.display_name}})}
if(method==='GET'&&path==='/api/account/export'){const x=await user(req,env);if(!x)return json({error:'unauthorized'},401);const [lib,prog,ent]=await Promise.all([env.DB.prepare('SELECT book_id,created_at FROM library_items WHERE reader_id=?').bind(x.reader_id).all(),env.DB.prepare('SELECT book_id,chapter_no,progress_pct,updated_at FROM reading_progress WHERE reader_id=?').bind(x.reader_id).all(),env.DB.prepare('SELECT chapter_id,source,granted_at,expires_at FROM entitlements WHERE reader_id=?').bind(x.reader_id).all()]);return json({profile:{id:x.reader_id,email:x.email,display_name:x.display_name},library:lib.results||[],progress:prog.results||[],entitlements:ent.results||[]})}
if(method==='DELETE'&&path==='/api/account'){const x=await user(req,env);if(!x)return json({error:'unauthorized'},401);await env.DB.prepare('DELETE FROM reader_profiles WHERE id=?').bind(x.reader_id).run();return json({ok:true,deleted:true},200,{'set-cookie':sessionCookie('',0)})}
if(method==='GET'&&path==='/api/library'){const x=await user(req,env);if(!x)return json({error:'unauthorized'},401);const q=await env.DB.prepare('SELECT b.id,b.title,b.author,b.genre,b.status,b.rating,b.chapter_count AS chapters,b.accent,b.description FROM library_items l JOIN books b ON b.id=l.book_id WHERE l.reader_id=? ORDER BY l.created_at DESC').bind(x.reader_id).all();return json({items:q.results||[]})}
m=path.match(/^\/api\/library\/([a-z0-9-]+)$/);if(m&&['POST','DELETE'].includes(method)){const x=await user(req,env),id=m[1];if(!x)return json({error:'unauthorized'},401);if(!bookOk(id))return json({error:'invalid_book'},400);const b=await env.DB.prepare('SELECT id FROM books WHERE id=?').bind(id).first();if(!b)return json({error:'book_not_found'},404);if(method==='POST'){await env.DB.prepare('INSERT OR IGNORE INTO library_items(reader_id,book_id) VALUES(?,?)').bind(x.reader_id,id).run();return json({ok:true,in_library:true})}await env.DB.prepare('DELETE FROM library_items WHERE reader_id=? AND book_id=?').bind(x.reader_id,id).run();return json({ok:true,in_library:false})}
if(method==='GET'&&path==='/api/progress'){const x=await user(req,env);if(!x)return json({error:'unauthorized'},401);const q=await env.DB.prepare('SELECT book_id,chapter_no,progress_pct,updated_at FROM reading_progress WHERE reader_id=?').bind(x.reader_id).all();return json({items:q.results||[]})}
m=path.match(/^\/api\/progress\/([a-z0-9-]+)$/);if(m&&method==='PUT'){const x=await user(req,env),id=m[1],b=await bj(req);if(!x)return json({error:'unauthorized'},401);const book=await env.DB.prepare('SELECT chapter_count FROM books WHERE id=?').bind(id).first();if(!book)return json({error:'book_not_found'},404);const ch=Math.max(1,Math.min(Number(book.chapter_count||1),Number(b.chapter_no||1)|0)),pct=Math.max(0,Math.min(100,Number(b.progress_pct||0)));await env.DB.prepare('INSERT INTO reading_progress(reader_id,book_id,chapter_no,progress_pct,updated_at) VALUES(?,?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(reader_id,book_id) DO UPDATE SET chapter_no=excluded.chapter_no,progress_pct=excluded.progress_pct,updated_at=CURRENT_TIMESTAMP').bind(x.reader_id,id,ch,pct).run();return json({ok:true,book_id:id,chapter_no:ch,progress_pct:pct})}
m=path.match(/^\/api\/books\/([a-z0-9-]+)$/);if(m&&method==='GET'){const book=await env.DB.prepare('SELECT id,title,author,genre,status,rating,chapter_count AS chapters,accent,description FROM books WHERE id=?').bind(m[1]).first();if(!book)return json({error:'book_not_found'},404);const q=await env.DB.prepare('SELECT chapter_no,title,is_free,coin_price,published_at FROM chapters WHERE book_id=? ORDER BY chapter_no').bind(m[1]).all();return json({book,chapters:q.results||[]})}
m=path.match(/^\/api\/books\/([a-z0-9-]+)\/chapters\/(\d+)$/);if(m&&method==='GET'){const id=m[1],n=Number(m[2]);const ch=await env.DB.prepare('SELECT c.id,c.book_id,c.chapter_no,c.title,c.body,c.is_free,c.coin_price,b.title AS book_title,b.chapter_count FROM chapters c JOIN books b ON b.id=c.book_id WHERE c.book_id=? AND c.chapter_no=?').bind(id,n).first();if(!ch)return json({error:'chapter_not_found'},404);let allowed=Number(ch.is_free)===1;if(!allowed){const x=await user(req,env);if(x){const e=await env.DB.prepare('SELECT 1 AS ok FROM entitlements WHERE reader_id=? AND chapter_id=? AND (expires_at IS NULL OR expires_at>CURRENT_TIMESTAMP)').bind(x.reader_id,ch.id).first();allowed=!!e}}if(!allowed)return json({locked:true,book_id:id,chapter_no:n,title:ch.title,coin_price:ch.coin_price},402);return json({locked:false,book_id:id,book_title:ch.book_title,chapter_no:n,title:ch.title,body:ch.body,coin_price:ch.coin_price,chapter_count:ch.chapter_count})}
m=path.match(/^\/api\/demo\/unlock\/([a-z0-9-]+)\/(\d+)$/);if(m&&method==='POST'){const x=await user(req,env);if(!x)return json({error:'unauthorized'},401);const ch=await env.DB.prepare('SELECT id FROM chapters WHERE book_id=? AND chapter_no=?').bind(m[1],Number(m[2])).first();if(!ch)return json({error:'chapter_not_found'},404);await env.DB.prepare("INSERT OR IGNORE INTO entitlements(reader_id,chapter_id,source) VALUES(?,?,'demo-phase3')").bind(x.reader_id,ch.id).run();return json({ok:true,demo:true,warning:'No real payment was charged.'})}
return json({error:'not_found'},404)}
export default{async fetch(req,env){const u=new URL(req.url);try{if(u.pathname.startsWith('/api/'))return await api(req,env,u);if(u.pathname==='/app.css')return reply(unwrap(await src('styles.js'),'export const CSS = `'),'text/css; charset=utf-8');if(u.pathname==='/app.js')return reply(unwrap(await src('client.js'),'export const CLIENT = String.raw`'),'text/javascript; charset=utf-8');return reply(unwrap(await src('ui.js'),'export const HTML = `'),'text/html; charset=utf-8')}catch(e){console.error(e);return json({error:'internal_error'},500)}}};
